const long long MOD = 998244353;
const long long G = 3;

long long power(long long base, int exp) {
    long long result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

void bitReverse(vector<long long>& array, int length) {
    int j = 0;
    for (int i = 1; i < length; i++) {
        int bit = length >> 1;
        for (; j >= bit; bit >>= 1) j -= bit;
        j += bit;
        if (i < j) {
            swap(array[i], array[j]);
        }
    }
}

void transform(vector<long long>& array, int length, int direction) {
    bitReverse(array, length);
    for (int size = 2; size <= length; size <<= 1) {
        long long root = power(G, (MOD - 1) / size);
        if (direction == -1) root = power(root, MOD - 2);
        for (int start = 0; start < length; start += size) {
            long long w = 1;
            for (int k = start; k < start + size / 2; k++) {
                long long u = array[k];
                long long v = array[k + size / 2] * w % MOD;
                array[k] = (u + v) % MOD;
                array[k + size / 2] = (u - v + MOD) % MOD;
                w = w * root % MOD;
            }
        }
    }
    if (direction == -1) {
        long long invLen = power(length, MOD - 2);
        for (int i = 0; i < length; i++) {
            array[i] = array[i] * invLen % MOD;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    int size = 1;
    int halfN = n / 2;
    while (size < (9 * halfN + 1)) size <<= 1;
    vector<long long> polyA(size, 0);
