    polyA[0] = 1;
    for (int i = 0; i < m; i++) {
        int x;
        cin >> x;
        polyB[x] = 1;
    }

    transform(polyA, size, 1);
    transform(polyB, size, 1);

    for (int i = 0; i < size; i++) {
        if (polyA[i] != 0 && polyB[i] != 0) {
            polyA[i] = polyA[i] * power(polyB[i], halfN) % MOD;
        } else {
            polyA[i] = 0;
        }
    }

    transform(polyA, size, -1);

    long long total = 0;
    for (int i = 0; i < size; i++) {
        total = (total + polyA[i] * polyA[i]) % MOD;
    }
    cout << total << "\n";
